package com.zomiggy.controller; import com.zomiggy.service.CatalogService; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api") public class CatalogController {private final CatalogService service; public CatalogController(CatalogService s){service=s;} @GetMapping("/restaurants") public Map<String,Object> restaurants(@RequestParam(required=false)String category,@RequestParam(defaultValue="false")boolean instantOnly){return Map.of("restaurants",service.restaurants(category,instantOnly));} @GetMapping("/dishes") public Map<String,Object> dishes(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false)Long restaurantId,@RequestParam(defaultValue="false")boolean vegOnly,@RequestParam(defaultValue="false")boolean instantOnly,@RequestParam(defaultValue="default")String sort){return Map.of("dishes",service.dishes(q,category,restaurantId,vegOnly,instantOnly,sort));} @GetMapping("/coupons") public Map<String,Object> coupons(){return Map.of("coupons",service.coupons());}}